        return Color(c.r, c.g, c.b, c.a)
    end
    return Color(
        c.r,
        c.g,
        c.b,
        math.floor(c.a * ____exports.clamp01(mul))
    )
end
function ____exports.dot(d, x, y, r, c, mul)
    d:drawDot(
        Vec2(x, y),
        r,
        ____exports.col(c, mul)
    )
end
function ____exports.seg(d, x0, y0, x1, y1, r, c, mul)
    d:drawSegment(
        Vec2(x0, y0),
        Vec2(x1, y1),
        r,
        ____exports.col(c, mul)
    )
end
function ____exports.circle(d, cx, cy, r, c, segments, mul)
    local n = segments == nil and 16 or segments
    do
        local i = 0
        while i < n do
            local a0 = i / n * math.pi * 2
            local a1 = (i + 1) / n * math.pi * 2
            ____exports.seg(
                d,
                cx + math.cos(a0) * r,
                cy + math.sin(a0) * r,
                cx + math.cos(a1) * r,
                cy + math.sin(a1) * r,
                2,
                c,
                mul
            )
            i = i + 1
        end
    end
end
function ____exports.arc(d, cx, cy, r, a0, a1, segments, radius, c, mul)
    do
        local i = 0
        while i < segments do
            local t0 = i / segments
            local t1 = (i + 1) / segments
            local ang0 = a0 + (a1 - a0) * t0
            local ang1 = a0 + (a1 - a0) * t1
            ____exports.seg(
                d,
                cx + math.cos(ang0) * r,
                cy + math.sin(ang0) * r,
                cx + math.cos(ang1) * r,
                cy + math.sin(ang1) * r,
                radius,
                c,
                mul
            )
            i = i + 1
        end
    end
end
function ____exports.torso(d, xL, xR, yTop, yBot, c, mul)
    d:drawPolygon(
        {
            Vec2(xL, yTop),
            Vec2(xR, yTop),
            Vec2(xR + 2, yBot),
            Vec2(xL - 2, yBot)
        },
        ____exports.col(c, mul),
        0,
        Color(0, 0, 0, 0)
    )
end
local function drawPonytail(d, hx, hy, facing, t)
    local sway = math.sin(t * 2.6) * 0.28
    local sway2 = math.sin(t * 3.4 + 1.2) * 0.22
    local px = hx - facing * 5
    local py = hy + 3
    local ang = math.pi - facing * (0.5 + sway)
    local lens = {11, 9, 7}
    local rads = {3, 2.3, 1.6}
    do
        local i = 0
        while i < 3 do
            ang = ang + (i == 0 and sway * 0.6 or sway2 * 0.8) - 0.12
            local nx = px + math.cos(ang) * lens[i + 1]
            local ny = py + math.sin(ang) * lens[i + 1]
            ____exports.seg(
                d,
                px,
                py,
                nx,
                ny,
                rads[i + 1],
                Palette.inkDark
            )
            px = nx
            py = ny
            i = i + 1
        end
    end
    local ra = math.pi + facing * (0.2 + sway2)
    ____exports.seg(
        d,
        hx - facing * 3,
        hy + 6,
        hx - facing * 3 + math.cos(ra) * 13,
        hy + 6 + math.sin(ra) * 13,
        1.4,
        ____exports.HeroScarf,
        0.9
    )
end
local function drawScarf(d, nx, ny, facing, t, pose)
    local stretch = 0
    local lift = 0
    if pose == "dash" then
        stretch = 1.5
        lift = 0.1
    elseif pose == "run" then
        stretch = 0.9
        lift = -0.15
    elseif pose == "fall" or pose == "jump" then
        stretch = 0.8
        lift = 0.5
    end
    local w1 = math.sin(t * 4.2) * 3.5
    local w2 = math.sin(t * 5.1 + 0.8) * 4.5
    local x1 = nx - facing * (12 + stretch * 8)
    local y1 = ny + lift * 10 + w1
    local x2 = nx - facing * (20 + stretch * 16)
    local y2 = ny + lift * 14 + w2
    ____exports.seg(
        d,
        nx,
        ny,
        x1,
        y1,
        3.4,
        ____exports.HeroScarf
    )
    ____exports.seg(
        d,
        x1,
        y1,
        x2,
        y2,
        2.2,
        ____exports.HeroScarf,
        0.75
    )
end
local function drawLeg(d, hx, hy, facing, phase, lift, bend)
    local kx = hx + facing * (4 + phase * 9 + bend * 4)
    local ky = hy - 19
    local fx = hx + facing * (4 + phase * 17 + bend * 8)
    local fy = hy - 36 + lift
    ____exports.seg(
        d,
        hx,
        hy,
        kx,
        ky,
        5,
        Palette.inkDark
    )
    ____exports.seg(
        d,
        kx,
        ky,
        fx,
        fy,
        4,
        Palette.inkDark
    )
end
function ____exports.drawHero(d, x, y, facing, pose, t, phaseIndex)
    local moonK = ____exports.clamp01(1 - math.abs(phaseIndex - 4) / 4)
    ____exports.dot(
        d,
        x,
        y + 40,
        34,
        Palette.moonWhite,
        0.06 + 0.1 * moonK
    )
    local bob = pose == "idle" and math.sin(t * 2) * 1.4 or 0
    local lean = 0
    if pose == "run" then
        lean = 0.18
    elseif pose == "dash" then
        lean = 0.55
    elseif pose == "attack1" or pose == "attack2" then
        lean = 0.3
    elseif pose == "attack3" then
        lean = 0.42
    elseif pose == "hurt" then
        lean = -0.35
    elseif pose == "jump" or pose == "cling" then
        lean = 0.1
    end
    local crouch = pose == "hurt" and -5 or (pose == "cling" and -3 or (pose == "ladder" and -2 or 0))
    local hipY = y + 36 + bob + crouch
    local shX = x + facing * math.sin(lean) * 16
    local shY = y + 60 + bob + crouch
    local hx = x + facing * math.sin(lean) * 24
    local hy = y + 72 + bob + crouch
    if pose == "run" then
        local sw = math.sin(t * 12)
        drawLeg(
            d,
            x,
            hipY,
            facing,
            sw,
            math.max(
                0,
                math.cos(t * 12)
            ) * 5,
            0
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            -sw,
            math.max(
                0,
                -math.cos(t * 12)
            ) * 5,
            0
        )
    elseif pose == "jump" then
        drawLeg(
            d,
            x,
            hipY,
            facing,
            0.7,
            14,
            -1
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            -0.3,
            8,
            -1
        )
    elseif pose == "fall" then
        drawLeg(
            d,
            x,
            hipY,
            facing,
            0.45,
            -2,
            1
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            -0.45,
            -4,
            1
        )
    elseif pose == "cling" then
        drawLeg(
            d,
            x,
            hipY,
            facing,
            0.5,
            6,
            -1.4
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            0.15,
            2,
            -1.2
        )
    elseif pose == "dash" then
        drawLeg(
            d,
            x,
            hipY,
            facing,
            1.5,
            4,
            0
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            -0.9,
            2,
            0
        )
    elseif pose == "ladder" then
        local sw = math.sin(t * 6)
        drawLeg(
            d,
            x,
            hipY,
            1,
            sw * 0.4,
            6 + sw * 4,
            0
        )
        drawLeg(
            d,
            x,
            hipY,
            1,
            -sw * 0.4,
            6 - sw * 4,
            0
        )
    else
        drawLeg(
            d,
            x,
            hipY,
            facing,
            0.35,
            0,
            0
        )
        drawLeg(
            d,
            x,
            hipY,
            facing,
            -0.3,
            0,
            0
        )
    end
    ____exports.torso(
        d,
        shX - 6.5,
        shX + 6.5,
        shY,
        hipY + 2,
        Palette.inkSoft
    )
    ____exports.seg(
        d,
        shX,
        shY + 2,
        x,
        hipY,
        8,
        Palette.inkSoft
    )
    local swordOut = pose == "attack1" or pose == "attack2" or pose == "attack3"
    if swordOut then
        local idx = pose == "attack1" and 0 or (pose == "attack2" and 1 or 2)
        local dur = ____exports.ATTACK_TIME[idx + 1]
        local p = ____exports.clamp01(t / dur)
        local handX = shX + facing * (16 + p * 8)
        local handY = shY - 4 + (idx == 2 and 12 - p * 26 or -p * 2)
        local bladeLen = idx == 2 and 40 or 32
        local ang = idx == 2 and 2.1 - p * 3.8 or -0.5 + p * 1.5
        ____exports.seg(
            d,
            handX,
            handY,
            handX + math.cos(ang) * bladeLen * facing,
            handY + math.sin(ang) * bladeLen,
            2.6,
            Palette.white,
            0.95
        )
        local a0 = facing > 0 and -0.7 or math.pi + 0.7
        local a1 = a0 + facing * (0.6 + p * 1.9)
        ____exports.arc(
            d,
            shX,
            shY - 4,
            bladeLen + 8,
            a0,
            a1,
            10,
            2,
            Palette.white,
            0.5 * (1 - p * 0.35)
        )
        local bx = shX - facing * 8
        ____exports.seg(
            d,
            shX,
            shY - 4,
            bx,
            shY - 16,
            3.6,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            bx,
            shY - 16,
            bx - facing * 6,
            shY - 22,
            3,
            Palette.inkDark
        )
    elseif pose == "ladder" then
        local sw = math.sin(t * 6)
        ____exports.seg(
            d,
            shX,
            shY,
            shX + 5,
            shY + 20 + sw * 5,
            3.6,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX,
            shY,
            shX - 5,
            shY + 20 - sw * 5,
            3.6,
            Palette.inkDark
        )
    elseif pose == "dash" then
        ____exports.seg(
            d,
            shX,
            shY,
            shX + facing * 16,
            shY - 6,
            3.6,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX,
            shY,
            shX - facing * 14,
            shY + 6,
            3.6,
            Palette.inkDark
        )
    else
        local armSw = pose == "run" and math.sin(t * 12) * 0.5 or 0
        ____exports.seg(
            d,
            shX + facing * 4,
            shY - 2,
            shX + facing * (8 + armSw * 8),
            shY - 16,
            3.8,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX - facing * 4,
            shY - 2,
            shX - facing * (8 - armSw * 8),
            shY - 16,
            3.8,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            x - facing * 6,
            hipY + 2,
            x - facing * 14,
            hipY - 12,
            2.4,
            ____exports.SteelGray,
            0.8
        )
    end
    ____exports.dot(
        d,
        hx,
        hy,
        7,
        Palette.inkDark
    )
    ____exports.dot(
        d,
        hx + facing * 3.4,
        hy - 1,
        2.6,
        Palette.paper
    )
    ____exports.dot(
        d,
        hx + facing * 4.2,
        hy,
        1,
        Palette.inkDark
    )
    drawPonytail(
        d,
        hx,
        hy,
        facing,
        t
    )
    drawScarf(
        d,
        shX,
        shY + 4,
        facing,
        t,
        pose
    )
end
function ____exports.drawEnemy(d, e, t)
    local x = e.body.x
    local feetY = e.body.y - e.body.h / 2
    local kind = e.def.kind
    local dying = e.dead and e.deathTimer > 0
    local aMul = dying and ____exports.clamp01(e.deathTimer / 0.55) or 1
    local squash = dying and 0.35 + 0.65 * aMul or 1
    local wide = 1 + (1 - squash) * 0.6
    local bodyH = e.body.h * squash
    local face = e.facing
    if e.state == "swing" or e.state == "charge" then
        do
            local g = 1
            while g <= 2 do
                local gx = x - face * g * 16
                local ga = 0.3 / g
                ____exports.torso(
                    d,
                    gx - e.body.w * 0.28,
                    gx + e.body.w * 0.28,
                    feetY + bodyH * 0.52,
                    feetY + bodyH * 0.9,
                    Palette.inkSoft,
                    ga
                )
                ____exports.dot(
                    d,
                    gx,
                    feetY + bodyH * 0.94,
                    kind == "boss" and 9 or 6.5,
                    Palette.inkSoft,
                    ga
                )
                g = g + 1
            end
        end
    end
    local hipY = feetY + bodyH * 0.42
    local shY = feetY + bodyH * 0.78
    local headY = feetY + bodyH * 0.92
    local headR = kind == "boss" and 9 or 6.5
    local jit = 0
    if e.state == "windup" or e.state == "telegraph" then
        jit = math.sin(t * 45) * 1.5
    end
    local lean = 0
    if e.state == "windup" then
        lean = -0.15
    elseif e.state == "swing" or e.state == "charge" then
        lean = 0.4
    elseif e.state == "hurt" then
        lean = -0.4
    elseif e.state == "patrol" then
        lean = 0.06 * math.sin(t * 3)
    end
    local shX = x + face * math.sin(lean) * 14 + jit
    local legLift = dying and -bodyH * 0.1 or (e.state == "charge" and 3 or 0)
    if kind == "boss" then
        ____exports.seg(
            d,
            x - 10,
            hipY,
            x - 15,
            feetY + legLift,
            7,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            x + 10,
            hipY,
            x + 16,
            feetY + legLift,
            7,
            Palette.inkDark
        )
    else
        local legSw = (e.state == "patrol" or e.state == "chase") and math.sin(t * 10) or 0
        ____exports.seg(
            d,
            x - 3,
            hipY,
            x - 6 - legSw * 6,
            feetY + legLift,
            4.5,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            x + 3,
            hipY,
            x + 6 + legSw * 6,
            feetY + legLift,
            4.5,
            Palette.inkDark
        )
    end
    local torsoW = kind == "boss" and e.body.w * 0.42 or e.body.w * 0.3
    ____exports.torso(
        d,
        shX - torsoW,
        shX + torsoW,
        shY,
        hipY + 2,
        Palette.inkSoft
    )
    ____exports.seg(
        d,
        shX,
        shY - 4,
        x,
        hipY,
        torsoW * 1.5,
        Palette.inkSoft
    )
    if kind == "bandit" then
        ____exports.seg(
            d,
            shX - torsoW,
            shY - 8,
            shX + torsoW,
            shY - 10,
            2.6,
            ____exports.EnemyGold,
            0.9
        )
        ____exports.dot(
            d,
            shX + face * 2 + jit,
            headY,
            headR,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX + face * 2 + jit,
            headY + headR * 0.6,
            shX + face * 8 + jit,
            headY + headR + 4,
            3.4,
            Palette.inkDark
        )
        ____exports.dot(
            d,
            shX + face * 4.4 + jit,
            headY + 1,
            1.8,
            Palette.paper
        )
        local armUp = e.state == "windup" and 18 or (e.state == "swing" and -6 or 4)
        local hx = shX + face * (torsoW + 4)
        local hy = shY - 6 + armUp
        ____exports.seg(
            d,
            shX,
            shY - 6,
            hx,
            hy,
            4,
            Palette.inkDark
        )
        local a0 = face > 0 and -0.9 or math.pi + 0.9
        local a1 = a0 + face * 1.7
        ____exports.arc(
            d,
            hx,
            hy,
            15,
            a0,
            a1,
            6,
            2.4,
            ____exports.SteelGray,
            aMul
        )
        ____exports.seg(
            d,
            hx,
            hy,
            hx + face * 14,
            hy + (e.state == "swing" and -4 or 9),
            1.6,
            ____exports.SteelGray,
            0.8 * aMul
        )
    elseif kind == "thrower" then
        local hunchX = shX + face * 6
        ____exports.dot(
            d,
            hunchX + face * 3 + jit,
            headY + 2,
            headR,
            Palette.inkDark
        )
        ____exports.dot(
            d,
            hunchX + face * 6 + jit,
            headY + 2,
            1.8,
            Palette.paper
        )
        ____exports.seg(
            d,
            shX,
            shY - 4,
            hunchX + face * 12,
            shY - 12,
            3.4,
            Palette.inkDark
        )
        local potX = hunchX + face * 13
        local potY = shY - 12
        ____exports.dot(
            d,
            potX,
            potY,
            6.5,
            Palette.inkWash
        )
        ____exports.seg(
            d,
            potX - 5,
            potY + 5,
            potX + 5,
            potY + 5,
            2,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX,
            hipY + 4,
            shX + face * 2,
            hipY - 4,
            1.6,
            ____exports.EnemyGold,
            0.8
        )
    else
        ____exports.dot(
            d,
            shX + face * 2 + jit,
            headY,
            headR,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX - 4 + jit,
            headY + headR * 0.7,
            shX - 9 + jit,
            headY + headR + 8,
            3,
            Palette.inkDark
        )
        ____exports.seg(
            d,
            shX + 6 + jit,
            headY + headR * 0.7,
            shX + 11 + jit,
            headY + headR + 8,
            3,
            Palette.inkDark
        )
        ____exports.dot(
            d,
            shX + face * 5 + jit,
            headY + 1,
            2.2,
            ____exports.EnemyRed
        )
        local swingK = e.state == "swing" and 1 or (e.state == "windup" and 0.2 or 0.5)
        local ang = face > 0 and -0.4 + swingK * 1.8 or math.pi + 0.4 - swingK * 1.8
        local bx = shX + face * 12
        local by = shY - 8
        local tipX = bx + math.cos(ang) * 52
        local tipY = by + math.sin(ang) * 52
        local nx = math.cos(ang + math.pi / 2) * 4
        local ny = math.sin(ang + math.pi / 2) * 4
        d:drawPolygon(
            {
                Vec2(bx + nx, by + ny),
                Vec2(tipX + nx * 0.4, tipY + ny * 0.4),
                Vec2(tipX - nx * 0.4, tipY - ny * 0.4),
                Vec2(bx - nx, by - ny)
            },
            ____exports.col(____exports.SteelGray, 0.85 * aMul),
            0,
            Color(0, 0, 0, 0)
        )
        ____exports.seg(
            d,
            bx,
            by,
            bx + math.cos(ang) * 46,
            by + math.sin(ang) * 46,
            3,
            Palette.inkDark,
            aMul
        )
        if e.phase2 then
            local pulse = 0.6 + 0.4 * math.sin(t * 5)
            ____exports.seg(
                d,
                shX - torsoW + 3,
                shY - 10,
                shX + torsoW - 3,
                shY - 16,
                2.2,
                ____exports.EnemyRed,
                pulse * aMul
            )
            ____exports.seg(
                d,
                shX - torsoW + 5,
                hipY + 12,
                shX + torsoW - 5,
                hipY + 18,
                2,
                ____exports.EnemyRed,
                pulse * aMul
            )
            ____exports.dot(
                d,
                shX,
                hipY + 6,
                3,
                ____exports.EnemyRed,
                pulse * aMul
            )
        end
        ____exports.seg(
            d,
            shX - torsoW,
            shY + 2,
            shX + torsoW,
            shY + 2,
            2.4,
            ____exports.EnemyGold,
            0.7
        )
    end
end
function ____exports.drawShenYan(d, x, y, facing, t, hostile)
