end
function ____exports.drawObserver(d, x, y, t)
    local pale = ink(196, 192, 182, 225)
    local bob = math.sin(t * 1.2) * 2
    local topY = y + 104 + bob
    local headY = y + 96 + bob
    d:drawPolygon(
        {
