    )
    ____exports.dot(
        d,
        x - 1.2,
        headY - 1,
        1,
        Palette.inkFaint
    )
    ____exports.dot(
        d,
        x + 1.2,
        headY - 1,
        1,
        Palette.inkFaint
    )
    local rot = t * 1.2
    local r = 16
    local nSeg = 10
    do
        local i = 0
        while i < nSeg do
            do
                if i % 2 == 0 then
                    goto __continue60
                end
                local a0 = rot + i / nSeg * math.pi * 2
                local a1 = rot + (i + 1) / nSeg * math.pi * 2
                ____exports.seg(
                    d,
                    x + math.cos(a0) * r,
                    headY + 22 + math.sin(a0) * r * 0.45,
                    x + math.cos(a1) * r,
                    headY + 22 + math.sin(a1) * r * 0.45,
                    1.8,
                    Palette.moonCyanSoft,
                    0.7
                )
            end
            ::__continue60::
            i = i + 1
        end
    end
end
